        if s.startswith('(*', i):
            depth += 1
            i += 2
            continue
        if depth and s.startswith('*)', i):
            depth -= 1
            i += 2
            continue
        if depth == 0:
            out.append(s[i])
        i += 1
    return ''.join(out)


