import re, sys

apply_path, new_path = sys.argv[1], sys.argv[2]
new = {}
for ln in open(new_path, encoding='utf-8'):
    ln = ln.rstrip('\n')
    m = re.match(r'- (F-\d+) ', ln)
    if m:
        new[m.group(1)] = ln
out = []
done = set()
for ln in open(apply_path, encoding='utf-8'):
    ln = ln.rstrip('\n')
    m = re.match(r'- (F-\d+) ', ln)
    if m and m.group(1) in new:
        out.append(new[m.group(1)])
        done.add(m.group(1))
    else:
        out.append(ln)
missing = set(new) - done
if missing:
    sys.exit('not found: %s' % sorted(missing))
open(apply_path, 'w', encoding='utf-8').write('\n'.join(out) + '\n')
t = n = 0
for ln in out:
    m = re.match(r'- (F-\d+) ', ln)
    if m:
        print(m.group(1), len(ln))
        t += len(ln)
        n += 1
print('total', t, 'n', n, 'budget', 600 * n)

